const params = new URLSearchParams();
params.append('client_id', 'cba-web');
params.append('grant_type', 'password');
params.append('username', 'admin@cba.com');
params.append('password', 'Admin@123');

fetch('http://localhost:8180/realms/cba/protocol/openid-connect/token', {
  method: 'POST',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: params
}).then(r => r.json()).then(data => {
  console.log('Access Token:', data.access_token);
});

OkHttpClient client = new OkHttpClient();
RequestBody body = new FormBody.Builder()
    .add("client_id", "cba-web")
    .add("grant_type", "password")
    .add("username", "admin@cba.com")
    .add("password", "Admin@123")
    .build();
Request request = new Request.Builder()
    .url("http://localhost:8180/realms/cba/protocol/openid-connect/token")
    .post(body)
    .build();
String response = client.newCall(request).execute().body().string();
System.out.println(response);

var client = new HttpClient();
var content = new FormUrlEncodedContent(new[]
{
    new KeyValuePair<string, string>("client_id", "cba-web"),
    new KeyValuePair<string, string>("grant_type", "password"),
    new KeyValuePair<string, string>("username", "admin@cba.com"),
    new KeyValuePair<string, string>("password", "Admin@123")
});
var response = await client.PostAsync(
    "http://localhost:8180/realms/cba/protocol/openid-connect/token", content);
Console.WriteLine(await response.Content.ReadAsStringAsync());

